solution.solution.cpp:
#include <cmath>

static float fraction(float mouseX, float trackStart, float trackWidth)
{
    if (trackWidth <= 0.0f) return 0.0f;
    const float t{ (mouseX - trackStart) / trackWidth };
    return t < 0.0f ? 0.0f : t > 1.0f ? 1.0f : t;
}

float valueFromMouse(float mouseX, float trackStart, float trackWidth, float minValue, float maxValue)
{
    return minValue + fraction(mouseX, trackStart, trackWidth) * (maxValue - minValue);
}

float positionOf(float value, float trackStart, float trackWidth, float minValue, float maxValue)
{
    if (trackWidth <= 0.0f || maxValue == minValue) return trackStart;
    float t{ (value - minValue) / (maxValue - minValue) };
    t = t < 0.0f ? 0.0f : t > 1.0f ? 1.0f : t;
    return trackStart + t * trackWidth;
}

int intValueFromMouse(float mouseX, float trackStart, float trackWidth, int minValue, int maxValue)
{
    const float v{ minValue + fraction(mouseX, trackStart, trackWidth) * static_cast<float>(maxValue - minValue) };
    return static_cast<int>(std::lround(v));
}

float logValueFromMouse(float mouseX, float trackStart, float trackWidth, float minValue, float maxValue)
{
    return minValue * std::pow(maxValue / minValue, fraction(mouseX, trackStart, trackWidth));
}

unitTests:
TEST("linear") { CHECK_NEAR(valueFromMouse(150, 100, 200, 0, 20), 5.0, 1e-5); CHECK_NEAR(valueFromMouse(300, 100, 200, -10, 10), 10.0, 1e-5); }
TEST("clamped") { CHECK_NEAR(valueFromMouse(0, 100, 200, 0, 20), 0.0, 1e-5); CHECK_NEAR(valueFromMouse(999, 100, 200, 0, 20), 20.0, 1e-5); }
TEST("reverse") { CHECK_NEAR(positionOf(5, 100, 200, 0, 20), 150.0, 1e-4); CHECK_NEAR(positionOf(-5, 100, 200, 0, 20), 100.0, 1e-4); CHECK_NEAR(positionOf(50, 100, 200, 0, 20), 300.0, 1e-4); }
TEST("integers round") { CHECK_EQ(intValueFromMouse(100 + 200 * 0.49f / 9.0f * 9.0f, 100, 200, 0, 9), 4); CHECK_EQ(intValueFromMouse(150, 100, 200, 0, 9), 2); CHECK_EQ(intValueFromMouse(300, 100, 200, 0, 9), 9); }
TEST("logarithmic") { CHECK_NEAR(logValueFromMouse(200, 100, 200, 0.01f, 100.0f), 1.0, 1e-4); CHECK_NEAR(logValueFromMouse(100, 100, 200, 0.01f, 100.0f), 0.01, 1e-6); CHECK_NEAR(logValueFromMouse(150, 100, 200, 0.01f, 100.0f), 0.1, 1e-5); }
TEST("empty track") { CHECK_NEAR(valueFromMouse(150, 100, 0, 3, 7), 3.0, 1e-6); CHECK_NEAR(positionOf(5, 100, 0, 3, 7), 100.0, 1e-6); }

